protected _compute_layout(): void {
  if (this.layout != null) {
    this.layout.compute(this.bbox.size)

    for (const child_view of this.layoutable_views) {
      if (child_view.layout == null) {
        child_view._compute_layout()
      } else {
        child_view._propagate_layout()
      }
    }
  } else {
    for (const child_view of this.layoutable_views) {
      child_view._compute_layout()
    }
  }
}

